import type { TimeOfDay } from './interpretation.js';

/**
 * IDs carried by interactive buttons / list rows / template quick replies.
 * They are generated by the backend and parsed strictly on the way back. The
 * offerId binds a choice to the exact question that was asked, so a button
 * pressed on an old message cannot act on a newer state. Appointment IDs in
 * reminder buttons are re-authorised against the sender (tenant + customer).
 */
export type ReplyAction =
  | { action: 'SLOT'; offerId: string; index: number }
  | { action: 'APPT'; offerId: string; index: number }
  | { action: 'SVC'; offerId: string; index: number }
  | { action: 'YES'; offerId: string }
  | { action: 'NO'; offerId: string }
  | { action: 'TOD'; offerId: string; value: TimeOfDay }
  | { action: 'HANDOFF'; offerId: string }
  | { action: 'APPT_CONFIRM'; appointmentId: string; version: number }
  | { action: 'APPT_CANCEL'; appointmentId: string; version: number };

const OFFER = '([a-z0-9]{6,16})';
const UUID = '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})';

export function encodeReplyId(a: ReplyAction): string {
  switch (a.action) {
    case 'SLOT':
    case 'APPT':
    case 'SVC':
      return `${a.action}:${a.offerId}:${a.index}`;
    case 'YES':
    case 'NO':
    case 'HANDOFF':
      return `${a.action}:${a.offerId}`;
    case 'TOD':
      return `TOD:${a.offerId}:${a.value}`;
    case 'APPT_CONFIRM':
    case 'APPT_CANCEL':
      return `${a.action}:${a.appointmentId}:${a.version}`;
  }
}

export function decodeReplyId(raw: string): ReplyAction | null {
  const id = raw.trim();
  let m = new RegExp(`^(SLOT|APPT|SVC):${OFFER}:(\\d{1,2})$`).exec(id);
  if (m) return { action: m[1] as 'SLOT' | 'APPT' | 'SVC', offerId: m[2] as string, index: Number(m[3]) };
  m = new RegExp(`^(YES|NO|HANDOFF):${OFFER}$`).exec(id);
  if (m) return { action: m[1] as 'YES' | 'NO' | 'HANDOFF', offerId: m[2] as string };
  m = new RegExp(`^TOD:${OFFER}:(MORNING|AFTERNOON|EVENING)$`).exec(id);
  if (m) return { action: 'TOD', offerId: m[1] as string, value: m[2] as TimeOfDay };
  m = new RegExp(`^(APPT_CONFIRM|APPT_CANCEL):${UUID}:(\\d{1,6})$`).exec(id);
  if (m) return { action: m[1] as 'APPT_CONFIRM' | 'APPT_CANCEL', appointmentId: m[2] as string, version: Number(m[3]) };
  return null;
}
